-- The public MAX demo uses one real supplier account and a focused fleet.
UPDATE suppliers
SET is_active = id = '20000000-0000-4000-8000-000000000001'::uuid
WHERE id IN (
  '20000000-0000-4000-8000-000000000001'::uuid,
  '20000000-0000-4000-8000-000000000002'::uuid,
  '20000000-0000-4000-8000-000000000003'::uuid
);

UPDATE equipment
SET is_available = false
WHERE id BETWEEN '10000000-0000-4000-8000-000000000001'::uuid
  AND '10000000-0000-4000-8000-000000000009'::uuid;

